import sys

from openai import OpenAI

sys.path.insert(0, "/home/codx-junior-projects/codx-junior/codx-junior-platform/api")

from codx.junior.global_settings import get_model_settings  # noqa: E402

MODEL = "deepseek-flash"
settings = get_model_settings(MODEL)
client = OpenAI(api_key=settings.api_key, base_url=settings.api_url)

TOOLS = [{
    "type": "function",
    "function": {
        "name": "get_date",
        "description": "Get the current date",
        "parameters": {"type": "object", "properties": {}},
    },
}]

FIRST = {"role": "user", "content": "What is the date today?"}
CALL_1 = {
    "role": "assistant",
    "content": None,
    "tool_calls": [{
        "id": "call_00_probe1",
        "type": "function",
        "function": {"name": "get_date", "arguments": "{}"},
    }],
}
CALL_1_COT = {**CALL_1, "reasoning_content": "I need the date."}
TOOL_RESULT = {"role": "tool", "tool_call_id": "call_00_probe1", "content": "2026-11-15"}
FINAL_NO_COT = {"role": "assistant", "content": "Today is 2026-11-15."}
FINAL_COT = {**FINAL_NO_COT, "reasoning_content": "I have the date."}
CALL_2 = {
    "role": "assistant",
    "content": "",
    "tool_calls": [{
        "id": "call_00_probe2",
        "type": "function",
        "function": {"name": "get_date", "arguments": "{}"},
    }],
}
CALL_2_COT = {**CALL_2, "reasoning_content": "Need it again."}
TOOL_RESULT_2 = {"role": "tool", "tool_call_id": "call_00_probe2", "content": "2026-11-15"}
LAST = {"role": "user", "content": "Thanks, now say bye in one word."}


def run(label, messages, extra_body=None, max_tokens=64):
    kwargs = {"model": MODEL, "messages": messages, "tools": TOOLS,
              "max_tokens": max_tokens}
    if extra_body:
        kwargs["extra_body"] = extra_body
    try:
        resp = client.chat.completions.create(**kwargs)
        msg = resp.choices[0].message
        cot = getattr(msg, "reasoning_content", None) or ""
        print(f"[OK]   {label}: reasoning_chars={len(cot)} "
