}).ratio), '1.0×')
check('touching calls do not overlap', turnMetrics({
  tool_events: [
    { tool: 'a', status: 'done', started_at: at(0), finished_at: at(1000) },
    { tool: 'b', status: 'done', started_at: at(1000), finished_at: at(2000) }
  ]
}).peak, 1)

// Derived position: finished_at only
const derived = toolIntervals({
  tool_events: [{ tool: 'a', status: 'done', finished_at: at(1000), duration_ms: 400 }]
}, 0)
check('derived start', derived.intervals[0].start, 1750000000600)
check('derived marks unmeasured', derived.measured, false)

// No timestamps at all: nothing is invented
const impossible = toolIntervals({ tool_events: [{ tool: 'a', status: 'done', duration_ms: 400 }] }, 0)
check('unplaced', impossible.unplaced, 1)
check('no fake parallelism', turnMetrics({ tool_events: [{ tool: 'a', status: 'done', duration_ms: 400 }] }).hasData, false)

// A running call grows with the clock of the parent
const running = turnMetrics({
  tool_events: [
    { tool: 'a', status: 'running', started_at: at(0) },
    { tool: 'b', status: 'running', started_at: at(0) }
  ]
}, 1750000002000)
check('running peak', running.peak, 2)
check('running toolMs', running.toolMs, 4000)

console.log(failures.length ? `\n${failures.length} FAILURE(S): ${failures.join(', ')}` : '\nall checks passed')
process.exit(failures.length ? 1 : 0)

/**
 * Ask the Vite dev server to COMPILE the touched modules (it transforms on
 * request) and report whether the SFCs and the util still build.
 * Run: node .codx/tmp/vite_check.mjs
 */
const modules = [
  '/src/utils/turnMetrics.js',
  '/src/components/chat/ChatTurnMetrics.vue',
  '/src/components/chat/ChatTurnTimeline.vue',
  '/src/components/chat/ChatMessageEvents.vue'
]
const ports = [8001, 5173, 3000]

const probe = async (port, path) => {
  const response = await fetch(`http://127.0.0.1:${port}${path}`)
  const body = await response.text()
  const failed = body.includes('Internal server error') || body.includes('Transform failed') || body.includes('Pre-transform error')
  return { status: response.status, bytes: body.length, failed, body }
}

const main = async () => {
  let base = null
  for (const port of ports) {
    try {
      const result = await probe(port, '/src/utils/turnMetrics.js')
      if (result.status === 200) {
        base = port
        console.log(`dev server on ${port}: ${result.bytes} bytes for the util`)
        console.log(result.failed ? 'COMPILE ERROR in turnMetrics.js' : 'turnMetrics.js compiles')
        break
      }
    } catch (error) {
      // port closed: try the next one
    }
  }
  if (!base) {
    console.log('no dev server reachable on ' + ports.join(', '))
    process.exit(1)
  }

  let failures = 0
  for (const path of modules.slice(1)) {
    const result = await probe(base, path)
    const ok = result.status === 200 && !result.failed
    if (!ok) {
      failures += 1
      console.log(`FAIL ${path} (status ${result.status})`)
      console.log(result.body.slice(0, 800))
    } else {
      console.log(`ok   ${path} · ${result.bytes} bytes compiled`)
    }
  }
  console.log(failures ? `${failures} module(s) failed to compile` : 'all modules compiled')
  process.exit(failures ? 1 : 0)
}

main()

/**
 * Which TCP ports does this container listen on? (Vite's port is not in the
 * environment, so read it from the kernel instead of guessing.)
 * Run: node .codx/tmp/ports.mjs
 */
import { readFileSync } from 'node:fs'

const decode = file => {
  const ports = new Set()
  let lines = []
  try {
    lines = readFileSync(file, 'utf8').split('\n').slice(1)
  } catch (error) {
    return ports
  }
  lines.forEach(line => {
    const columns = line.trim().split(/\s+/)
    if (columns.length < 4) return
    const local = columns[1]
    const state = columns[3]
    if (state !== '0A') return // 0A = LISTEN
    const port = parseInt(local.split(':')[1], 16)
    if (port) ports.add(port)
  })
  return ports
}

const ports = new Set([...decode('/proc/net/tcp'), ...decode('/proc/net/tcp6')])
console.log('listening ports:', [...ports].sort((a, b) => a - b).join(', '))

